{
  "schemaVersion": "0.2",
  "slug": "hover-card",
  "name": "HoverCard",
  "status": "experimental",
  "purpose": "Reveals supplementary content when the pointer hovers over a trigger.",
  "scenarios": [
    "Show a preview card",
    "Display a user profile tooltip",
    "Reveal a definition"
  ],
  "props": {
    "trigger": {
      "type": "node",
      "required": true,
      "description": "Hover trigger element."
    },
    "children": {
      "type": "node",
      "required": true,
      "description": "Content shown on hover."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "open",
      "description": "Card is visible."
    },
    {
      "name": "closed",
      "description": "Card is hidden."
    }
  ],
  "composition": {
    "allowedParents": [
      "page",
      "card",
      "button"
    ],
    "allowedChildren": [
      "text",
      "button"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use for touch-only interfaces.",
    "Do not hide critical content inside hover."
  ],
  "a11y": {
    "role": "dialog",
    "keyboard": [
      "Focus trigger may show card",
      "Esc dismisses"
    ],
    "focus": "Focus remains on trigger; card is not focusable.",
    "labeling": "Children provide the content label.",
    "wcag": [
      "1.4.13"
    ]
  },
  "responsive": {
    "strategy": "Positioned popover.",
    "breakpoints": {
      "compact": "May be suppressed.",
      "medium": "Hover only.",
      "large": "Hover only."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "hover-card",
    "states": [
      "open",
      "closed"
    ],
    "intents": [
      "preview-detail"
    ]
  }
}

import { PopoverPrimitive } from '@chameleon-ui/primitives'
import { useState } from 'react'
import type { ReactNode } from 'react'
import './styles.css'

export interface HoverCardProps {
  trigger: ReactNode
  children: ReactNode
  className?: string
}

export function HoverCard({ trigger, children, className }: HoverCardProps) {
  const [open, setOpen] = useState(false)
  const classes = ['cu-hover-card', className].filter(Boolean).join(' ')

  return (
    <PopoverPrimitive.Root
      open={open}
      onOpenChange={(details) => setOpen(details.open)}
    >
      <PopoverPrimitive.Trigger
        asChild
        className="cu-hover-card__trigger"
        onMouseEnter={() => setOpen(true)}
        onMouseLeave={() => setOpen(false)}
        onFocus={() => setOpen(true)}
        onBlur={() => setOpen(false)}
      >
        {trigger}
      </PopoverPrimitive.Trigger>
      <PopoverPrimitive.Positioner>
        <PopoverPrimitive.Content
          className={classes}
          data-ai-role="hover-card" data-ai-intent="preview-detail"
          data-ai-state={open ? 'open' : 'closed'}
          onMouseEnter={() => setOpen(true)}
          onMouseLeave={() => setOpen(false)}
        >
          {children}
        </PopoverPrimitive.Content>
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Root>
  )
}

.cu-hover-card {
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  box-shadow: var(--cu-shadow-md, 0 1px 3px color-mix(in srgb, var(--cu-color-background-inverse) 12%, transparent));
  z-index: 10;
}

.cu-hover-card__trigger {
  display: inline-flex;
}
